mapper.select:
select d.id, d.category_id, d.name, d.image, d.price, d.status, d.create_time, d.update_time, d.create_user, d.update_user, c.name as categoryName
from dish d left join category c on d.category_id = c.id

     and d.category_id = #{categoryId}
     and d.name like concat('%', #{name}, '%')
     and d.status = #{status}
 order by d.create_time desc
